"""Audit an Excel model that was generated by a script (or by an AI agent) before it goes to anyone.

It recalculates the workbook with a formula engine independent of Excel and then looks for the
defects that a generated file tends to have and that opening it once does not show.

Run: python audit.py model.xlsx
Exit code 1 if any finding is an error.
"""
import re
import sys
import zipfile
from collections import defaultdict
from pathlib import Path

import formulas
import numpy as np
import openpyxl
from openpyxl.utils import get_column_letter, range_boundaries

LITERAL_OK = set("$-+/():!^&'~{}<>= ")        # characters Excel accepts unquoted in a number format
FORMAT_TOKENS = re.compile(r'"[^"]*"|\\.|\[[^\]]*\]|[0#?.,%;@*_ ]|[dmyhsDMYHS]+|AM/PM|General|E[+-]', re.I)


def flat(rng):
    v = rng.value if hasattr(rng, "value") else rng
    return np.asarray(v, dtype=object).ravel()[0]


def recalculated_errors(path):
    """Every formula cell, recalculated outside Excel: error values and empty results."""
    sol = formulas.ExcelModel().loads(str(path)).finish().calculate()
    out = []
    for key, rng in sol.items():
        m = re.search(r"\](.+?)'!([A-Z]+\d+)$", key)       # single cells only: '[book.xlsx]SHEET'!A1
        v = flat(rng)
        if m and isinstance(v, str) and v.startswith("#"):
            out.append(("error", f"{m.group(1)}!{m.group(2)}", f"recalculates to {v}"))
    return out, len(sol)


def text_stored_as_formula(wb):
    """A note that starts with '=' is saved as a formula and shows #NAME? in Excel."""
    out = []
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for c in row:
                if c.data_type == "f" and isinstance(c.value, str) and re.match(r"^=\s+[A-Za-zÁÉÍÓÚáéíóú]", c.value):
                    out.append(("error", f"{ws.title}!{c.coordinate}", f"text stored as a formula: {c.value[:40]!r}"))
    return out


def overlapping_merges(wb):
    """Two merged ranges that overlap make Excel 'repair' the file on opening."""
    out = []
    for ws in wb.worksheets:
        boxes = [(str(r), range_boundaries(str(r))) for r in ws.merged_cells.ranges]
        for i, (a, (a0, a1, a2, a3)) in enumerate(boxes):
            for b, (b0, b1, b2, b3) in boxes[i + 1:]:
                if a0 <= b2 and b0 <= a2 and a1 <= b3 and b1 <= a3:
                    out.append(("error", f"{ws.title}!{a}", f"merged range overlaps {b}"))
    return out


def values_lost_in_merges(wb):
    """Merging wipes every cell except the top-left one. A formula that points there reads empty."""
    hidden = set()
    for ws in wb.worksheets:
        for r in ws.merged_cells.ranges:
            c0, r0, c1, r1 = range_boundaries(str(r))
            hidden |= {(ws.title, f"{get_column_letter(c)}{rw}") for c in range(c0, c1 + 1)
                       for rw in range(r0, r1 + 1) if (c, rw) != (c0, r0)}
    out = []
    ref = re.compile(r"(?:'([^']+)'|([A-Za-z_][\w.]*))?!?\$?([A-Z]{1,3})\$?(\d+)")
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for c in row:
                if c.data_type != "f":
                    continue
                for q, u, col, rw in ref.findall(str(c.value)):
                    sheet = q or u or ws.title
                    if (sheet, f"{col}{rw}") in hidden:
                        out.append(("error", f"{ws.title}!{c.coordinate}",
                                    f"points to {sheet}!{col}{rw}, a cell wiped by a merge"))
    return out


def hardcoded_in_formula_rows(wb, min_formulas=4):
    """A typed number in the middle of a row of formulas: the classic override nobody remembers."""
    out = []
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            cells = [c for c in row if c.value is not None]
            f = [c for c in cells if c.data_type == "f"]
            n = [c for c in cells if c.data_type == "n" and not c.is_date]
            if len(f) >= min_formulas and 0 < len(n) <= 2 and f[0].column < n[0].column < f[-1].column:
                for c in n:
                    out.append(("warning", f"{ws.title}!{c.coordinate}",
                                f"typed value {c.value} inside a row of {len(f)} formulas"))
    return out


def broken_number_formats(path):
    """A number format with an unquoted literal makes Excel report 'a problem with some content'."""
    out = []
    with zipfile.ZipFile(path) as z:
        styles = z.read("xl/styles.xml").decode("utf-8")
    for code in re.findall(r'formatCode="([^"]*)"', styles):
        code = (code.replace("&quot;", '"').replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">"))
        if code.count('"') % 2:
            out.append(("error", "styles", f"number format with an unpaired quote: {code}"))
            continue
        rest = FORMAT_TOKENS.sub("", code)
        bad = sorted({ch for ch in rest if ch not in LITERAL_OK})
        if bad:
            out.append(("error", "styles", f"number format with unquoted {''.join(bad)!r}: {code}"))
    return out


def audit(path):
    path = Path(path)
    wb = openpyxl.load_workbook(path)                 # formulas as text
    findings, n_cells = recalculated_errors(path)
    for fn in (text_stored_as_formula, overlapping_merges, values_lost_in_merges, hardcoded_in_formula_rows):
        findings += fn(wb)
    findings += broken_number_formats(path)
    by_kind = defaultdict(list)
    for kind, where, what in findings:
        by_kind[kind].append((where, what))
    print(f"{path.name}: {n_cells} cells recalculated · {len(by_kind['error'])} error(s) · {len(by_kind['warning'])} warning(s)")
    for kind in ("error", "warning"):
        for where, what in by_kind[kind]:
            print(f"  {kind:<7} {where:<22} {what}")
    return not by_kind["error"]


if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    results = [audit(p) for p in sys.argv[1:]]
    sys.exit(0 if all(results) else 1)
